package me.timschneeberger.rootlessjamesdsp.fusion

import android.app.Application
import org.junit.Assert.*
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.RuntimeEnvironment
import org.robolectric.annotation.Config

@RunWith(RobolectricTestRunner::class) @Config(sdk=[35],application=Application::class)
class DdcParametersTest {
    private val p=DdcParameters
    private val sha="00112233445566778899aabbccddeeff0123456789abcdef0123456789abcdef"
    @Test fun defaultsCarryExactlyTheContractAndNoEnabledProfessionalGroup(){val s=p.defaults();assertTrue(s.valid());assertEquals(20,p.numbers.size);assertEquals(34,p.newKeys.size);assertFalse(s.professional);p.switches.filterNot {it==p.LINKED}.forEach {assertEquals(false,s.values()[it])};assertTrue(s.linked);val v=s.packet();assertEquals(64,v.size);assertEquals(1,v[0]);assertEquals(1000,v[4]);assertEquals(120,v[7]);assertEquals(8000,v[11]);assertEquals(1000,v[15]);assertEquals(6000,v[19]);assertEquals(1,v[23]);assertEquals(10,v[33]);assertTrue(v.drop(36).all {it==0});assertFalse(s.values().containsKey(p.ENABLED));assertFalse(s.values().containsKey(p.FILE))}
    @Test fun allTwentyNumbersPreserveExactMinMaxAndSmallestInputSteps(){for(control in p.numbers){for(n in listOf(control.min,control.default,control.max)){assertEquals(control.key,n,control.parse(control.number(n)));val v=p.defaults().values().toMutableMap();v[control.key]=n;val s=p.capture(v);assertTrue(s.valid());assertEquals(n,s.values()[control.key])};assertNull(control.parse(control.number(control.max+1)));assertNull(control.parse("NaN"));assertNull(control.parse("Infinity"));if(control.decimals>0)assertNull(control.parse("0."+"0".repeat(control.decimals)+"1"))}}
    @Test fun littleEndianShaWordsRetainAllSignedBitsAndRoundTripOriginalDigest(){val words=p.shaWords(sha);assertEquals(0x33221100,words[0]);assertEquals(0x77665544,words[1]);assertEquals(0xbbaa9988.toInt(),words[2]);assertEquals(sha,p.sha256(words.toList()));assertNull(p.sha256(List(8){0}));assertArrayEquals(words,p.defaults().packet(true,sha).copyOfRange(36,44));assertEquals(1,p.defaults().packet(true,sha)[2]);assertThrows(IllegalArgumentException::class.java){p.shaWords("bad")}}
    @Test fun settingsRoundTripEveryDormantFieldWithoutEnablingAnyGroup(){val v=p.defaults().values().toMutableMap();p.numbers.forEach {v[it.key]=if(it.default==it.max)it.default-1 else it.default+1};val s=p.capture(v);assertTrue(s.valid());assertEquals(v,s.values());assertFalse(s.professional);val packet=s.packet(false,sha);assertEquals(0,packet[1]);assertEquals(0,packet[2]);assertEquals(999,packet[4]);assertEquals(121,packet[7]);assertEquals(0,packet[5]);assertTrue(packet.drop(44).all {it==0})}
    @Test fun allNumberRangesRemainValidatedEvenWhenProfessionalIsOff(){for(control in p.numbers){val values=p.defaults().values().toMutableMap();values[control.key]=control.max+1;assertEquals(control.default,p.value(values,control))};assertFalse(p.defaults().copy(peak1Q=1001).valid());assertFalse(p.defaults().copy(margin=121).valid());assertFalse(p.defaults().copy(preamp=-481).valid());assertFalse(p.defaults().copy(output=121).valid());assertThrows(IllegalArgumentException::class.java){p.defaults().copy(ratio=-1).packet()}}
    @Test fun rightEarSavedValuesAreUnavailableOnlyWhileLinkedAndGroupsCloseIndependently(){val v=p.defaults().copy(professional=true,ratioOn=true,compensationOn=true,lowOn=true,highOn=true,peak1On=true,peak2On=true,earOn=true,preampOn=true,autoHeadroomOn=true,outputOn=true,rightRatio=317,rightLevel=-29).values();assertTrue(p.numberEnabled(p.leftRatio.key,v));assertFalse(p.numberEnabled(p.rightRatio.key,v));assertFalse(p.numberEnabled(p.rightLevel.key,v));val independent=v+mapOf(p.LINKED to false);assertTrue(p.numberEnabled(p.rightRatio.key,independent));assertEquals(317,p.capture(independent).rightRatio);assertEquals(-29,p.capture(independent).rightLevel);for(control in p.numbers)assertTrue(control.key,p.numberEnabled(control.key,independent));for(control in p.numbers)assertFalse(p.numberEnabled(control.key,independent+mapOf(p.PROFESSIONAL to false)));assertFalse(p.numberEnabled(p.lowGain.key,independent+mapOf(p.COMPENSATION_ON to false)));assertTrue(p.numberEnabled(p.ratio.key,independent+mapOf(p.COMPENSATION_ON to false)))}
    @Test fun normalizationNeverRewritesTheSelectedFilePowerOrOtherNamespaces(){val app:Application=RuntimeEnvironment.getApplication();val prefs=DdcController.preferences(app);prefs.edit().clear().putString(p.FILE,"DDC/original.vdc").putBoolean(p.ENABLED,true).putString(p.ratio.key,"bad").putInt(p.lowFrequency.key,999999).commit();p.normalize(prefs);assertEquals("DDC/original.vdc",prefs.getString(p.FILE,null));assertTrue(prefs.getBoolean(p.ENABLED,false));assertEquals(1000,prefs.getInt(p.ratio.key,0));assertEquals(120,prefs.getInt(p.lowFrequency.key,0));p.apply(prefs,p.defaults().copy(professional=true,ratio=317));assertEquals("DDC/original.vdc",prefs.getString(p.FILE,null));assertTrue(prefs.getBoolean(p.ENABLED,false));assertTrue(p.validSavedFoundation(prefs.all));prefs.edit().putInt(p.FILE,123).commit();assertFalse(p.validSavedFoundation(prefs.all));p.normalize(prefs);assertEquals(123,prefs.getInt(p.FILE,0))}
    private fun runtime()=IntArray(80).apply {this[0]=1;this[1]=2;this[2]=48000;this[16]=96000;this[17]=48000;this[18]=128;this[20]=Int.MIN_VALUE;this[32]=1000;this[33]=1000;p.shaWords(sha).copyInto(this,36);p.shaWords(sha).copyInto(this,62)}
    @Test fun runtimeDecoderAcceptsBothFileIdentitiesAndIndependentHostRateButRejectsInvalidFields(){val v=runtime();val r=requireNotNull(p.decode(v));assertEquals(48000,r.rate);assertEquals(sha,r.activeSha256);assertEquals(sha,r.acceptedSha256);for((i,n)in listOf(0 to 2,1 to 3,2 to 7999,3 to 2,6 to 7,8 to 5,9 to 2001,10 to 1,18 to 129,20 to 36001,29 to 1,30 to -481,31 to 121,32 to 1001,34 to 121,44 to 24001,48 to 60001,50 to 2,51 to 17,59 to 36001,60 to 2,70 to 1)){assertNull("slot$i",p.decode(v.copyOf().apply {this[i]=n}))};assertNull(p.decode(v.copyOf(79)))}
    private fun response()=IntArray(232).apply {this[0]=1;this[1]=2;this[2]=48000;this[3]=1;this[4]=32;for(i in 0 until 32){this[8+i*7]=20+i*700;this[9+i*7]=-36000;this[10+i*7]=137;this[11+i*7]=-317;this[14+i*7]=1}}
    @Test fun highRateWorkingKernelsKeepTheAcceptedFileShaInsteadOfRejectingTheWholeAcknowledgement(){
        for(rate in listOf(8000,44100,48000,88200,96000,176400,192000,384000,768000)){
            val words=runtime().apply {this[2]=rate;this[16]=rate;this[17]=rate;this[5]=1;this[15]=1}
            val decoded=requireNotNull(p.decode(words)){"Rejected $rate Hz DDC acknowledgement"}
            assertEquals(rate,decoded.rate);assertTrue(decoded.fileReady);assertEquals(sha,decoded.acceptedSha256)
            assertEquals(sha,decoded.activeSha256)
        }
        for(rate in listOf(-1,7999,768001,Int.MAX_VALUE))assertNull(p.decode(runtime().apply {this[17]=rate}))
        assertNotNull(p.decode(runtime().apply {this[17]=0}))
    }
    @Test fun responseDecoderKeepsThreeDistinctCurvesAndRejectsInvalidOrZeroCancellationSentinels(){val v=response();val r=requireNotNull(p.decodeResponse(v));assertEquals(32,r.points.size);assertEquals(listOf(20,-36000,137,-317,0,0,1),r.points.first());for((i,n)in listOf(1 to 3,4 to 31,9 to Int.MIN_VALUE,10 to 36001,11 to -36001,12 to 1,14 to 2,15 to 20)){assertNull("slot$i",p.decodeResponse(v.copyOf().apply {this[i]=n}))};assertNull(p.decodeResponse(v.copyOf(231)));assertNotNull(p.decodeResponse(IntArray(232).apply {this[0]=1;this[4]=32}))}
}
